from fastapi.security import SecurityScopes, OAuth2PasswordBearer
from fastapi.testclient import TestClient

app = FastAPI()
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="token")

def dep_inner(security_scopes: SecurityScopes):
    return security_scopes.scopes

def dep_outer(scopes_inner: SecurityScopes = Depends(dep_inner)):
    return scopes_inner.scopes

@app.get("/test")
def read_root(scopes: SecurityScopes = Security(dep_outer, scopes=["outer_scope"])):
    return {"scopes": scopes.scopes}

client = TestClient(app)

def test_hierarchical_security_scopes():
    # We need to bypass the actual OAuth2 authentication to test scope propagation
    # So we override the oauth2_scheme
    app.dependency_overrides[oauth2_scheme] = lambda: "fake-token"

    response = client.get("/test")
    assert response.status_code == 200
    # The final SecurityScopes should contain both the outer scope and any inner scopes
    # In this case, dep_outer is called with ['outer_scope'].
    # dep_inner is a dependency of dep_outer.
    # If dep_inner also had scopes, they should be merged.
    assert "outer_scope" in response.json()["scopes"]

def test_nested_scopes():
    def dep_deep(security_scopes: SecurityScopes):
        return security_scopes.scopes

    def dep_mid(scopes_deep: SecurityScopes = Depends(dep_deep)):
        return scopes_deep.scopes

    @app.get("/nested")
    def read_nested(scopes: SecurityScopes = Security(dep_mid, scopes=["mid_scope"])):
        return {"scopes": scopes.scopes}

    app.dependency_overrides[oauth2_scheme] = lambda: "fake-token"
    response = client.get("/nested")
    assert response.status_code == 200
    assert "mid_scope" in response.json()["scopes"]

